import type { HelpBook } from './helpTypes'

export const helpManualEn: HelpBook={
 '/':{title:'Home',summary:'Your personal operational view of the day. An incident report opens from the “+ Incident report” button at the foot of the menu.',audience:'All users with Home access',chapters:[
  ['Orientation','The Dashboard is not identical for every user. It adapts to your role, scope, additional capabilities and current assignments.'],
  ['What needs attention','Start with pending items and notifications. Selecting a task takes you directly to the corresponding operational record.'],
  ['Fast display','Home shows the numbers of your previous visit at once and refreshes them within a few seconds; while they refresh, «Updating…» is shown. These numbers are kept only in your own browser and are removed when you sign out.'],
  ['Quick actions','Use only the actions available for your role. If an action is not visible, the related permission has not been granted.'],
  ['Filters and search','In every list the Filters button opens a window with the filters. When you are done press OK to close it, without having to click elsewhere on the screen. When a filter is set, Clear filters appears next to OK: it removes all of them and closes the window. In the list each filter in force shows once, as a label with ×: press the × to remove it. Once you type in the search, an × appears inside the field on the right that clears it. The search finds anything the row shows: code, name, department, date, status, organism, owner. Accents and capitals do not matter, and with two words (e.g. «icu klebsiella») only the rows that have both stay. In a questionnaire’s results it searches every answer (not only the comments), the department, the channel and the date.'],
  ['The Hospital Administrator home','The Hospital Administrator, and the Platform Owner inside a hospital, see the Home on one screen without scrolling, on a computer and a tablet. At the top five figures, only of the modules the hospital has enabled: “Active surveillance” (with how many are in isolation, or “no one in isolation”), “Samples to review” (positives with no surveillance decision; when they cannot be counted the figure is left out), “Overdue controls” (in how many departments), “Overdue corrective actions” (of how many open) and “Expired certificates” of suppliers, not renewed; each figure opens its screen. On the left “Departments with the most pending items”: up to eight departments, as many as fit, each with a horizontal bar — red the overdue controls, amber the overdue corrective actions, grey the expired staff certificates — and the total on the right; the line opens the screen of its largest part and “All departments” opens Controls. Below it “Also need a decision”, only what the figures do not already show: critical laboratory results not communicated, antimicrobial therapies awaiting approval, objectives not met, minutes pending, supplier certificates expiring within 30 days, “Training requests” (which open that tab in Training) and more; when there is nothing it says “Nothing else pending”. On the right “The week”: seven lines, today and the next six days, with what each day holds as small labels in the Calendar’s colours — controls and cultures as a count (today also in how many departments), expiries and documents as a count, trainings and meetings by name when there are one or two; the line opens the Calendar on that day. Under it the “Announcements” in one line, with “Mark all read” and “Open”.'],

  ['The Division Director home','The title is the division name, with the number of departments, the staff categories and the month. Four cards give the totals: Staff (on leave and new in the last 30 days), next month rosters (published rosters and uncovered nights), Training (target at least 90%) and Flu vaccination (with no flu record since 1 September it reads «No records» instead of 0%). The table Departments I oversee has one row per department with its roster (Published, Draft with the uncovered nights, or Missing), requests, training, flu, hand hygiene and the falls and pressure ulcers of the last 30 days; a row opens the department read only. On the right are what needs attention (a missing roster, requests waiting over 3 days, training expiring within 30 days), the upcoming interviews and the next 7 days. With more than one division, the Division choice at the top right switches division. The role sees the rosters, requests, staff, training, controls, registers and incident reports of its departments without approving, changing or publishing anything.']
 ],steps:['Review today’s pending work.','Open the task that requires action.','Return to the Dashboard and continue with the next priority.'],preview:'dashboard'},
 '/my-department':{title:'My department',summary:'Department-level work, obligations and visibility within your own scope.',audience:'Department managers and department users',chapters:[
  ['Department view','Department managers receive a broader operational view. Standard department users see only the information required for their assigned daily work.'],
  ['The Department Manager’s home','The Department Manager sees the whole picture of the department on one screen, without scrolling. On the title’s line, on the right, they choose the period: “Month”, “Quarter”, “Half-year” or “Year”, with the ‹ › arrows the previous or the next one, and the “Compare” with the previous period, with the same period last year or “No comparison” (then no changes and no grey line show). At first the current month against the previous one; the subtitle says which period is shown and what it is compared with (e.g. “Quarter Oct–Dec 2026 compared with Jul–Sep 2026”), and the choice of kind and comparison is remembered on this computer. At the top four figures for the period, each with its change from the comparison period (e.g. “▲ +3 (+38%)”): red when things get worse, green when they get better. “Positive samples” (how many MDR/XDR and how many “to review”, that is positive with no episode and no decision by the infection control team), “New episodes / isolations” (surveillance episodes and isolations that started in the period, with the day’s reassessments), “Hand hygiene” (compliance in the period, with the hospital’s target or 80% and the number of observations; the change in points) and “Controls out of time” (controls of the period done outside their window and controls that fell overdue in the period and are still not done, with today’s overdue ones). Below them “Positive samples per week” (Month, Quarter) or “per month” (Half-year, Year), MDR/XDR and other, with the comparison period as a grey dashed line in the same position (week 1 with week 1); hovering over a bar shows the numbers. Beside it “Department organisms” for the period, in numbers only and without patient names: positive samples, patients, MDR/XDR and kinds of organism, the 4 most frequent organisms with a bar (the MDR/XDR part in the chart’s colour) and beside each the difference from the comparison period (“+2”, “−1”, nothing when equal), and the other kinds on one line. At the bottom: “For me today” (including roster requests waiting and training due within 30 days); in the middle “Register: …” when the department has an active register (e.g. ICU, NICU, emergency, obstetrics): its 4 main indicators for the period, those past the limit or below target first, each with its value, its change from the comparison period, its status and target, and “Open” to the register’s indicators; a department without a register sees “Hand hygiene per month” there (the months of the period, at least the last 6) with the target dashed and the comparison period in grey and, when hand hygiene is not enabled in the hospital, “Department incidents” of 30 days (falls, pressure ulcers, medication errors, other incidents and how many are still open). These cards have a fixed number of lines and do not scroll. On the right “Announcements” with “The department (30 days)”: falls / pressure ulcers (when the incidents card does not already show them), training completion and staff flu vaccination. “For me today”, the announcements and “The department (30 days)” do not change with the period. A positive result that is the laboratory’s contamination note does not count as a positive sample. Each figure and chart opens the matching list when the role has access to it. Anything that belongs to a module the hospital has not enabled is not shown. The hospital-wide “Indicators” do not appear in the Department Manager’s menu: the department’s figures are on this screen and in the department’s register. The Link Nurse and the Department User keep the previous view.'],
  ['The department calendar','In «Calendar» the Department Manager sees the «Department calendar» with the department’s name (no «Department» choice, since there is one). «Month» tab: the whole month fits the screen without scrolling. Each day says in one line what each item is, e.g. «Training: Hand hygiene», with a coloured dot per category; up to three lines and, when there are more, «+N» beside the day’s number. Overdue items are red and their day has a red bar on the left; weekends are slightly grey. The categories on top (Controls, Cultures, Trainings, Department meetings, Expiries, Other) show how many the month has and hide or show with one click. On the right: «The month at a glance» (the month’s overdue items, what is left this week, trainings, expiries), the chosen day (today at first; click a day to see it) and «Next 7 days», with «expires» on expiries; when not everything fits, the day’s «+N more» opens the whole day in a window and that of the 7 days opens the to-do list. Clicking an item opens its record. «To do» tab: a table of «Overdue» or «Next 30 days», with a search and the same categories. The same item of many employees (e.g. a certificate expiry) is one row with «N employees»; clicking the row opens the list of the people, and clicking a person opens their record. The «Overdue by» column says how long it has been overdue (e.g. «11 months», «18 days»).'],
  ['The home of the Department User and the Link Nurse','The Department User and the Link Nurse open a home of their own in «My department», on one screen without scrolling (the Department Manager keeps theirs). At the top, four figures: «Department overdue» (the department’s controls and cultures that are late; red when there are any, it opens «To do» of the department calendar), «For today» (today’s tasks: controls, samples, isolation reassessments, as in «For me today»), «My certificates» (your own training certificates that expire within 90 days or have expired) and «In isolation now» (how many of the department’s patients are in isolation: the number only, never names; not shown when Surveillance is locked). Below, three columns: on the left «For me today» and under it «My trainings» (up to four: overdue, in progress with the due date, a certificate that expires, completed); in the middle «Next 7 days in the department», with the tag «mine» on what concerns you and the link «Department calendar»; on the right «Updates & announcements». When a list does not fit, it scrolls inside its card.'],
  ['What the calendar shows to each role','The roles of the whole hospital see in the calendar what their role allows, as before. The department roles (Department Manager, Department User, Link Nurse) see their department’s items and the Division Director those of the division’s departments; whatever has no department (for example a supplier evaluation, an audit without a department) is not shown. A training shows in a department when its «Audience» names the department (for example «ICU · Internal Medicine») or concerns everyone («All staff», «Clinical staff»). Certificate expiries: the Department User and the Link Nurse see only their own, without colleagues’ names; the Department Manager and the Division Director those of the whole department. The departments see only their own «Department meetings»; the hospital committees’ sessions and decisions do not show in a department’s calendar. The same holds for «Next 7 days» on the home.'],
  ['Shift roster: holidays, limits and checks','The page opens with no department chosen: pick the department first (someone with a single department sees it at once). Each person’s target (“Shifts / target”, “Hours”) is the working days of the period (Monday–Friday without public holidays) × 8 hours, less leave; e.g. 21/11–20/12: 20 shifts, 160 hours. Automatic generation follows an order of priority: first the rules that bind, then the cover of the basic shifts (nights first), and only then each person’s target, a fair share (mornings, afternoons, nights, Saturdays, Sundays, holidays, in proportion to each person’s availability), the quality of the days off, wishes and supplementary shifts; no smaller preference leaves a shift without its people. Above the roster the line “Needed · Available · Margin” shows whether there are enough people (by shift on hover). In “Other shifts of the department” each shift is “Basic” (must be covered) or “Supplementary” (given to people left over, never a shortage); the intermediate starts as supplementary. The supernumerary (e.g. the head) is not counted in the coverage: shown as “+1” beside the count. Between two shifts always 11 hours of real rest, from their times (e.g. afternoon 15–23 then morning 07 is not allowed). After one night one day off; after two nights two. By exception, only to cover a shift, the roster may give one day off after two nights, a third night or a second stretch of six (shown as recommendations). “Morning or intermediate → night the next day” is set per department in the Rules. Public holidays (with the movable Easter ones) are marked on the roster by themselves with «PH»; type the local feast in the Rules (day/month and name). A holiday counts as a weekend day, and in the staffing the «Holidays» column sets its own number of people (at first as many as on weekends). Click an employee\u2019s name to set «No nights» (pregnancy, breastfeeding, a medical reason, other) with an optional end date: while it holds, the roster gives them no night. «Leave & wishes» also has «Not this shift (mandatory)», never broken (not even by a shift entered by hand: the check shows it), and «Wishes a shift», kept where possible. Entering the same «Not this shift» again for the same days removes it. In the Rules set the most hours a week (on average; one week may hold one more shift; part-time in proportion). Automatic generation counts every shift by its real hours: in a department of 12-hour shifts (07:00–19:00 / 19:00–07:00) it gives fewer shifts a week and more days off, so the limit holds. Under the roster the checks are split into “Binding conflict” (red), “Short of staff” and “Recommendation” (e.g. a shift within the two days around a leave); “Full cover” shows only when no basic shift is short.'],
  ['My pending work','Controls, training, follow-up and other assignments are gathered here so users do not need to search across the whole application.'],
  ['NICU register: indicators','Besides the basic ones, the NICU has indicators from what it already records: % keeping breast milk (of any kind), % preterm (< 37 and < 32 weeks), % low and very low birth weight, % on mechanical ventilation and on CPAP, % with an umbilical catheter, % and mean days of a PICC (percutaneous central line; one field, also for the old PICC records), % on parenteral nutrition and % transferred to another hospital. Late-onset infections count per 1,000 central-line days (PICC and umbilical together). When a yes/no of the indicator was left empty, «entry missing (N)» shows beside the value, because it counts as «no». For the «exclusive breast milk» indicator choose «Exclusive» or «Mixed» in the form instead of «Yes»; while no entry tells them apart, the indicator reads «Not recorded» instead of 0%.'],
  ['ICU and NICU registers: device days','After the ventilator hours the ICU register has two fields: «Central line days» and «Urinary catheter days» (write 0 when there was none). In the NICU the central-line days are the PICC together with the «Umbilical catheter days», filled in whenever there is an umbilical catheter. The register’s «Indicators» tab shows the patient-days (total) and the central line, urinary catheter (ICU) and ventilator utilisation: device days per 100 patient-days, in the month of discharge; in the ICU the ventilator days are the hours divided by 24. While no entry has a device’s days, the indicator reads «Not recorded». From the same days the infection control team gets the unit’s CLABSI, CAUTI and VAP per 1,000 device days (Indicators, with the department filter).'],
  ['NICU register: possible late-onset infections','NICU neonates\u2019 positive blood cultures taken 72 hours or more after admission carry the tag «Possible late-onset infection · NICU (day N)» in Surveillance › «To review». Infection control decides there: «Open episode» records «Confirmed late-onset infection» in the NICU register automatically and the indicator counts it; «No surveillance needed» (e.g. contamination) does not count. The NICU «Late-onset infections» indicator shows two values per 1,000 line days: the main one, «Confirmed», on which the target is judged, and beneath it «Possible», every blood culture waiting for a decision or confirmed (not the rejected ones), with how many still wait for a decision. On each neonate’s register card, while such a blood culture waits for a decision, «Possible late-onset infection: waiting for a decision» shows with the organism and the day of the stay, and the «To review» button opens the Surveillance list. It is only a hint: it does not change the «Confirmed late-onset infection» field. The infection control team, the reviewing doctor, the hospital administrator and the Platform Owner decide. The match with the laboratory happens in the database; no name leaves the department. The NICU «Late-onset infections» indicator says how many still wait for a decision. Several at once: «To review» › «Only possible late-onset infections», tick them and «Open episodes» or «No surveillance needed». Automatic NICU rule: every validated positive blood culture of a neonate opens a surveillance episode by itself (or joins the open one) with the note «Automatic NICU rule»; if taken ≥72 hours after admission, the register records «Confirmed late-onset infection». For skin organisms (CoNS etc.) this happens only when the same neonate has a second such positive blood culture within 48 hours; otherwise they stay in «To review».'],
  ['Outbreaks: possible clusters','In Surveillance › «Outbreaks» the «Possible clusters» (3 or more positive results of the same organism in the same department within 14 days) are a paged table: organism, department, patients and samples, period, resistance. There are no buttons on the rows: click a cluster and the «New outbreak investigation» opens filled in with the organism, the department and the period. At the top right the switch «Possible clusters | Investigations» shows one list at a time, on the whole screen; the search looks in the list shown. Inside each investigation, the steps bar shows where you are: 1 Start, 2 Review the cases (e.g. 2/4), 3 Actions (how many are open), 4 Closure. Clicking a step opens its tab; «Closure» opens the closure review while the investigation is active. An investigation has two tabs. «Cases»: a paged table (date, patient with the code and the name below it, department, specimen, organism and resistance, infection and devices, review); click a row and the human case review opens, while the investigation is not closed. «Actions & decisions»: the corrective actions and the hypotheses or decisions. At the top right there is one main button depending on the step («Start investigation» or «Review closure») and «Export»; the timeline and the evidence trail are in the PDF report.'],
  ['Printing a register and PDF','In a register\u2019s Export menu, Print and PDF first open a small window. For Indicators choose the Layout (Summary: indicator and value; Detailed: also numerator, target and assessment) and the Comparison: none, the previous period, the same period last year, or another period by its dates. For entries and sheets choose the Period (all, or from–to) and the Layout (Summary: the list\u2019s columns; Detailed: every field). The document carries the hospital logo, aligned tables and signatures, and also opens in Word. The choices are remembered.'],
  ['Register definition','In a register\u2019s «Definition» the three tabs Register, Fields and Indicators sit right under the register\u2019s tabs. «Register» has the name, the status, the date a case counts on and the identity kept, and below a summary: fields by section, indicators, entries since when and who records. In «Fields» each section opens and folds from its band; each row has a handle to drag it to another place or section, its type, «required» and the «⋯» on the right (Edit, Move to section, Move up/down, Withdraw; the data is kept). «As the department sees it» shows the new-entry form with the fields as they are now, read-only. «Indicators» shows the type, the target and limit, «Better when» and the value of the last complete month. Edit opens a centred card; for an indicator the card shows live the value the new settings give. The bar «Undo changes / Save · N changes» appears only when there are changes.'],
  ['NICU register: age in hours','The «Admission» section has «Time of admission» and «Time of birth» (24-hour, hh:mm). With both times filled in, «Age on admission in hours» is calculated on Greek time and cannot be typed over; the admission time cannot come before the birth. Without the times, the age in hours is typed by hand, as in FileMaker. For neonates under 3 days old the age is shown in hours.']
 ],steps:['Review personal and department pending work.','Open the assigned task from the list.','Complete or document only the work assigned to your scope.'],preview:'department'},
 '/my-profile':{title:'My record',summary:'Your personal employee record and the information you are allowed to access.',audience:'Employees',chapters:[
  ['Personal details','The record displays work identity, department, position and employment status. Administrative data cannot be freely changed by the employee.'],
  ['Training & certificates','You can review your own training assignments, completions and available certificates.'],
  ['Employee health','Occupational-health information remains separated and is displayed only where explicit authorization exists.']
 ],steps:['Review the information in your record.','Open the section available to your role.','Request administrative corrections from the authorized role when needed.'],preview:'profile'},
 '/patients':{title:'Patients',summary:'Patient registry and entry point to the surveillance record.',audience:'Infection Control and authorized clinical roles',chapters:[
  ['Patient search','Always search before creating a new patient record to reduce the risk of duplicate records.'],
  ['Organism / isolation','The column shows each patient’s latest organism from a positive culture, resistant or not, with the resistance tag (e.g. MDR) beside it when there is one and the isolation when it is in place. The list’s search finds anything the row shows: name, code, department, admission date, status, organism and resistance, regardless of accents and capitals; with two words (e.g. «nicu coli») it finds those that have both.'],
  ['Patient record','The patient record brings together demographics and linked surveillance episodes. Available actions depend on your permission set.'],
  ['Patients with samples to review','The infection control team, the reviewing doctor, the hospital administrator and the Platform Owner see a tick box only on the patients with a positive sample awaiting a decision (the same as «To review»); the other patients have none. Tick one or more patients (or all of them from the header, on every page, as the filters show them) and the same bar as «To review» appears above the pages: «N selected», «Open episodes», «No surveillance needed» and «Clear selection». The actions apply to every sample awaiting a decision of the ticked patients: one episode per patient, or one reason for all. Afterwards the tick box leaves the patients decided. The other roles see the list as before.'],
  ['New patient','A new patient can be created only by users with Create permission and only with the minimum required information.']
 ],steps:['Search for the patient first.','Open the existing record or create a new one if permitted.','Continue to the linked surveillance episode.'],preview:'registry'},
 '/surveillance':{title:'Surveillance',summary:'Complete infection-surveillance workflow from initial assessment to outcome. One section with tabs: Surveillance episodes, Patients, Outbreaks, Employees, Environment.',audience:'Infection Control lead/team and authorized clinical roles',chapters:[
  ['Surveillance episode','Each episode is treated as one continuous record. Avoid creating disconnected parallel records for the same episode.'],
  ['Clinical assessment','Record the clinical information required for HAI assessment and the patient’s current clinical picture.'],
  ['Microbiology & AMR','Laboratory data are reused from the Laboratory module. MDR/XDR/PDR assessment is based on available validated microbiology results.'],
  ['Therapy & isolation','Antimicrobial therapy, isolation precautions, dates and reassessments remain within the same episode timeline.'],
  ['Sepsis: protocols & qSOFA','qSOFA is a scale of “Clinical assessments” (respiratory rate ≥ 22, altered mentation / GCS < 15, systolic BP ≤ 100). When a saved assessment gives qSOFA ≥ 2 or a SOFA rise ≥ 2 from the previous one of the admission, “Possible sepsis — start a protocol?” appears. From the episode, “Start protocol” → “Sepsis Hour-1 bundle” or “Septic shock”. The “Sepsis” section appears only once a protocol is started: time of recognition, 5 actions with their time or “Not indicated” with a reason, green / amber / red against the 60 minutes, complete or close, and the history. While it is open, the list shows “Sepsis”. Decision support, not a diagnosis (Sepsis-3, Surviving Sepsis Campaign 2021).'],
  ['Forms & questionnaires','One tab of the patient and surveillance record with every form connected to the episode, in collapsible sections. Each row has a title, a status in plain words (Pending, Completed, Overdue), the last date and one action. “Device prevention bundles”: per device, with the device day and compliance %; a new check starts only from the device row (“Bundle check”, “Surveillance & samples” tab) with patient, surveillance, device and day prefilled. “Scales”: the former “Clinical assessments”. The NEWS2, Braden and GCS chips in the header open the section. “Notifiable diseases”: every notifiable finding of the episode (or report of the patient, even with no admission) with the disease, date and status of the notification to the public health authority; “New notification” or “Open”. Visible only to the administrator, the infection control team and the laboratory. “Incidents”: the incidents linked to the episode; “Incident report” opens the same incident form prefilled with the patient, admission and surveillance. At the end, only for roles with access to outbreak investigations: “Linked to an outbreak” with the investigation, department and number of cases (read-only). “Staff exposure” on the employee surveillance record (/surveillance/staff/…, occupational physician only): the exposure incidents with source, prophylaxis and follow-up; “Record exposure” with the employee and record prefilled. The source patient shows only a number, “Source of staff exposure: N employees”, never names; “View” only for the occupational physician.'],
  ['Epidemiological questionnaire','One questionnaire per surveillance episode, as the “Epidemiological history” section of the “Forms & questionnaires” tab: 11 questions answered Yes / No / Unknown. The 3 core questions (antibiotics in the last 90 days, ICU, transfer from another hospital or facility) are required, but “Unknown” counts as an answer, so nobody is blocked. What the record already holds (therapy, ICU, devices, admission source) is prefilled and marked “Prefilled from”. The line in the episode header shows the origin (hospital when onset is more than 48 hours after admission, otherwise outside the hospital) and the risk factors in words. The “Increased risk of a multidrug-resistant organism” signal is advisory and does not decide isolation. The culture request and the sample entry show only the 3 core questions and write to the same questionnaire. A pending questionnaire shows as “Questionnaire: pending” in the list. The administrator changes the wording in Management Center › Libraries & settings › Questionnaires.'],
  ['48–72 h antimicrobial review','In “Antimicrobial therapy”, 48 hours after the start a review card appears (overdue after 72): Continue, De-escalate, Switch to oral or Stop, with a reason, a note, who and when. The roles that manage antimicrobial therapy record it. Limoxis does not suggest a drug.'],
  ['Reassessment & outcome','Only authorized roles can close an episode. Completion remains traceable in the record history.'],
  ['Infection report','In the Export of the Patients list, Infection report prints, makes a PDF or a Word file of the episodes the list’s filters keep (e.g. Department: NICU). Before printing you choose the Layout (Summary or Detailed), the Period (everything or from–to) and the Comparison (none, the previous period, the same period last year or other dates). It holds a summary (episodes, patients, HAI, positive cultures, resistance, and HAI per 1,000 patient days when the patient days cover the whole period; if the HAI classification cannot be read, it shows “—”) and tables with a chart by microorganism, resistance, site of infection, department and month. Detailed adds the list of the episodes with the patient code, never names.'],
  ['To review: several samples at once','In «To review» every row has a tick box and the header «Select all». With the «Department» filter and «Only possible late-onset infections (≥ 72 hours)» only, e.g., the NICU blood cultures remain. The rows have no buttons: tick one or more samples and a bar «N selected» appears above the pages with «Open episode(s)», «No surveillance needed» and «Clear selection». The list holds every positive sample awaiting a decision, however old. The tick in the header selects the whole list as the filters show it, on every page (e.g. the whole NICU), and the bar says so. With a single sample the usual episode form opens (with the choice of stay). The list has pages, like the others. For the ticked ones: «Open episodes» opens one episode per patient (the same neonate\u2019s samples go to the same episode, dated by the first sample), and the NICU register records the confirmed late-onset infection as with one at a time; «No surveillance needed» asks one reason for all. Any not done are listed at the end and stay in the list. The same can be done from the «Patients» list, ticking patients instead of samples.']
 ],steps:['Open the active surveillance episode.','Review the timeline and missing information.','Complete the appropriate clinical or laboratory-related section.','Reassess isolation and outcome when required.'],preview:'surveillance'},
 '/laboratory':{title:'Laboratory',summary:'Samples, microbiology, AST and critical results without duplicate data entry.',audience:'Laboratory and authorized users',chapters:[
  ['Laboratory queue','The Laboratory landing page highlights pending samples, results and critical laboratory work. The list shows the last 12 months (by collection date) and the samples not finished yet; «All samples» in the «Period» filter brings the older ones.'],
  ['Sample & result','A sample remains linked to its subject/source and progresses to a result without creating a second disconnected record.'],
  ['AST & resistance','Susceptibility data use the central organism and antimicrobial libraries to support consistent recording.'],
  ['Critical communication','Critical-result communication is documented with time, recipient and responsible user.'],
  ['Infection report','In the Export of the Samples tab, Infection report prints, makes a PDF or a Word file of the patients’ positive samples the list’s filters keep (search, department, status, result, “today” or “pending”; samples older than 12 months are read when the period asks for them). You choose the Layout, Period and Comparison as in Surveillance. It holds a summary (positive samples, patients, resistance, positive patients per 1,000 patient days, always with the patient days entered in the library and only when they cover the whole period) and tables with a chart by microorganism, resistance, sample type, department and month; Detailed adds the list of the samples. Employee and environmental samples do not count.']
 ],steps:['Open the pending work queue.','Select the relevant sample.','Record or validate the result and AST.','Document critical communication when required.'],preview:'laboratory'},
 '/prevention':{title:'Prevention',summary:'Prevention tools displayed according to role and capability.',audience:'Infection Control and users with the relevant assigned responsibility',chapters:[
  ['Hand hygiene','Record WHO observations using standardized fields and calculated compliance.'],
  ['Prevention bundles','CLABSI, CAUTI, VAP/VAE, SSI and other bundles use versioned criteria with Yes/No/N/A responses.'],
  ['Antiseptics & waste','These workflows are visible only to users with the appropriate operational responsibility.'],
  ['Use of data','Prevention records feed indicators and analytics without unnecessary duplicate entry.']
 ],steps:['Choose the prevention workflow.','Set department and period using the filters.','Record the observation or bundle assessment.','Review the calculated result before saving.'],preview:'prevention'},
 '/controls':{title:'Controls',summary:'Execution of assigned controls with evidence and independent status by department. The day-by-day programme is in the Calendar (filter “Controls”).',audience:'Users with a control assignment or Controls permission',chapters:[
  ['To execute','Shows controls assigned to you or to your permitted organizational scope.'],
  ['Executing a control','Open the task, review the criteria, record the result and attach evidence where required.'],
  ['What executors cannot change','Executors do not change frequency, programme, departments or governance settings for the control.'],
  ['Completion','Each department completes its own obligation. Completing one scope does not close outstanding assignments for other scopes.']
 ],steps:['Open “To execute”.','Select the control.','Complete each criterion and supporting evidence.','Finish only after reviewing the full entry.'],preview:'controls'},
 '/quality':{title:'Quality Center',summary:'Incidents, audits, findings and CAPA within controlled workflows.',audience:'Quality Manager and authorized roles',chapters:[
  ['Incidents','An incident progresses through statuses and an audit trail. It should not simply disappear because a user changes their mind. The list always opens newest first: by date, and within the same day by time and code. Clicking another column changes the order until the list is opened again.'],
  ['Voiding and deleting a record','The ⋯ menu of a record (incident, finding, corrective action, audit) has Void record and Delete. Voiding keeps the record as voided in the history. Deleting moves it, with everything that depends on it, to the Recycle Bin: from there it can be restored or deleted for good within 30 days, after which it is removed automatically. The Platform Owner, the Hospital Admin and the Quality Manager can delete; the database checks the same.'],
  ['Findings & CAPA','Findings can be linked to corrective/preventive actions with owners, deadlines and effectiveness follow-up.'],
  ['Audits','Audits and their findings remain linked to follow-up actions and evidence.'],
  ['Risk assessment','A risk register on the 5×5 (NHS) matrix: inherent, residual and target risk for every risk (likelihood × consequence) with the score and level computed, heat maps, comparison between years or semesters, JCI mapping, CAPA from a risk, import from Excel (the hospital risk assessment form) and a full printout.'],
  ['Deviation assessment','Every deviation shows its Flow on the right: Found, Assessment, Corrective action, Effectiveness, Closed, with a button for the next step. The Assessment tab records the severity, the kind of deviation, whether it recurs, the categories and the analysis of the causes, and the decision Is a corrective action needed? With Yes the New corrective action button appears. With No a reason is required, the Corrective action and Effectiveness steps read Not needed, and the deviation does not count as without action. A deviation that already has a corrective action counts as assessed with Yes. The assessment keeps who made it and when.']
 ],steps:['Open the relevant queue.','Select the incident, audit or finding.','Record the assessment and actions.','Follow CAPA through controlled completion.'],preview:'quality'},
 '/indicators':{title:'Indicators',summary:'Measurable monitoring with explicit numerator, denominator, target and drill-down. For management, “Indicators” in the menu is the executive dashboard and this list is in Management Center › Indicator definitions.',audience:'Infection Control, Quality and authorized management roles',chapters:[
  ['Indicator definition','Every indicator has a definition, unit, numerator, denominator, multiplier, target and direction.'],
  ['Automatic calculation','Where reliable source data exist, the indicator is calculated without duplicate manual entry.'],
  ['Drill-down','Each displayed value should be explainable through the source data that produced it.'],
  ['Indicators without the Surveillance module','If the hospital’s package does not include Surveillance, the indicators computed only from it (active surveillance per 1,000 patient-days, active surveillance with resistance, new MDR isolations overall and per pathogen, CLABSI, CAUTI, VAP, NICU CLABSI by birth weight, surgical site infections) are not shown, instead of appearing with 0. This applies to the Indicators list, Indicator definitions, the indicator choice for an objective, a committee plan or a risk, and the infections report. Indicators from the laboratory and patient-days (bacteraemias, multidrug-resistant bacteraemias, antibiotic resistance) and from the other modules keep working; a short line in the list explains it.'],
  ['CLABSI, CAUTI and VAP in the ICU and NICU','With the ICU or NICU department filter, «CLABSI / CAUTI / VAP per 1,000 days» take the denominator from the unit’s register when Surveillance records no devices: each stay counts its days within the period (a stay without discharge up to today) and its device days are shared out in proportion. The numerator counts only the cases the infection control team marked as hospital-acquired; the type «Catheter-associated urinary tract infection (CAUTI)» counts in CAUTI. There are also the central line, urinary catheter and ventilator utilisation (device days per 100 patient-days) and the NICU CLABSI in the five NHSN birth-weight bands (≤750, 751–1000, 1001–1500, 1501–2500, >2500 g). For the whole hospital, CLABSI, CAUTI and VAP leave out the ICU and NICU when they have their own register-based indicators. When device days are missing the indicator shows «—», not 0.'],
  ['Exporting reports','In Reports the Export menu has one Print and one PDF for the tab you are viewing. To export another section, open its tab first. The Summary also has the Board report.'],
  ['Summary: status today and period performance','«Summary» fits on one screen: «Status today» at the top, «Period performance» below on the left and «Need attention» on the right. «Need attention» lists first, in red, what is off target or got worse, then, in amber, drops that stay on target and overdue training. «Status today» shows as cards what is pending now, whenever it began (overdue controls, open incidents, overdue corrective actions, training, certificates, committee decisions); these are not compared with an earlier period. «Period performance» shows only what compares, with the period value, the comparison, the change and the target. Under each abbreviation its meaning is written (e.g. HAI: healthcare-associated infections). HAI is counted as confirmed only, everywhere; if surveillance episodes are not classified, «Need attention» says so first. «Hospital-acquired bacteremias» (a positive blood culture acquired in hospital) compare with the same period last year. Hand hygiene, bundles and training show the same figure and the target set by the hospital (Objectives) on every tab; green from the target, amber up to 10 points below, red further down. On every tab the figures are small cards with the comparison value and the change below (e.g. «2025: 70.1% · +2.7 pts»); those that show the state today read «today · not compared». In the bars by department a thin grey line marks the comparison, with the change beside the value, and in «Departments» the comparison value is written under each value. «Expired certificates not renewed» (here and on Home) counts only those not replaced by a newer one of the same type.'],
  ['Kitchen satisfaction','The Questionnaires tab lists a separate “Kitchen satisfaction” questionnaire (SRV-KITCHEN). It gathers the “Food” questions (food quality, meal service) of every patient questionnaire and shows the kitchen’s satisfaction on its own, against an 80% target. It is read-only: responses are entered and corrected in the questionnaire they came from. A questionnaire made from the “Kitchen questionnaire” template is listed as itself.'],
  ['Printing a questionnaire and PDF','In a questionnaire’s Results, Export › Print or PDF opens a window with three choices. Layout: Summary (the satisfaction of each question with its bar) or Detailed (also the answers 1–5 as a coloured bar, the choice questions, by department, by month and the comments). Period: all responses or from–to (the dates of the screen’s filter come in already). Compare with: none, the previous period of the same length, the same period last year or another period; the comparison column shows the earlier value and the change in points. The comparison also reads the earlier questionnaires of the same kind (e.g. last year’s ward questionnaire). The screen’s department, channel and search filters also apply to the document. Every table has the same columns with the same widths. Green bar: at or above the target; orange: below it. The same document also downloads as Word. It works for “Kitchen satisfaction” too.']
 ],steps:['Choose the reporting period and scope.','Review the value and target.','Open drill-down when investigation is required.'],preview:'indicators'},
 '/training':{title:'Training',summary:'Different workspaces for training administrators and employees.',audience:'Training administrators and employees',chapters:[
  ['For administrators','Create programmes, manage participants and attendance, publish material, assessments, results and certificates.'],
  ['For employees','At the top right the choice “Mine | My department | Whole hospital”. The Department User and the Link Nurse start on “Mine”, the Department Manager on “My department” and a role with a view of the whole hospital on “Whole hospital” (“My department” shows when the account has a department). In “Mine” each programme is one line with its latest assignment; when it was assigned more than once it reads e.g. “3 times · latest 10/9/2026”. The list has “In progress | Completed | All” with counts, search and pages: title with category and method, due date with “in N days” or the delay, status, result (score, “Review pending” or “Completed”) and certificate with its expiry (orange when it expires within 90 days, red when expired). Each open training has the “Start” button (or “Continue” once started) and a submitted one without a certificate “Result”: they open the same page as the invitation e-mail’s link, without needing the e-mail; with a certificate there is a small download button. “My department” and “Whole hospital” show only training programmes, one per line, never a list of employees (cancelled ones left out): “Training” with category, type and trainer, “Period”, “Intended for”, “Department participation” (numbers only, e.g. “12 of 20” completed, with a small bar; “—” when nobody of the department is assigned; without a department, the hospital’s totals), “Status” (In progress, Planned, Completed) and “Me”. “My department” and the “Department” filter show the programmes the department organised (the Department Manager’s department training, or when the “Organizer / owner” is the department or a person of the department) and those it attended, that is with participants from the department. Programmes only intended for the department or the whole staff, with no participants from it, show in “Whole hospital” with Department “All”. The “Organised by” column names the department that organised each programme (or “—”) and “Department participation” counts the participants of the chosen department. “Filters” has “Department” (any department of the hospital; in “My department” your own at first), “Status” (Current, Planned, Completed, All) and “Category”; the filters in force show as small tags with ×. The four figures are “Programmes in progress”, “Planned” (with the next start), “Pending in the department” (how many of the department’s participations in running programmes are not completed; in “Mine” it becomes “To complete” with the next due date) and “My requests” (pending, and how many were rejected). The “Me” column shows one item: the button of your own training when you take part, “Completed”, “Request pending” with a small × next to it (“Cancel request”: after confirming with “Withdraw request” the request is withdrawn and “Request to attend” shows again), “Rejected” (the reason shows when you hover over it; while the programme is not completed, “New request” sits next to it) or the “Request to attend” button for a programme that is not completed: it opens a small window with an optional note and the request goes to the training managers; once accepted, the training appears under “Mine”. When the request is accepted or rejected, the requester gets a notice in the bell (“Notifications”): “Your request for “…” was accepted” or “… was rejected” with the reason; clicking it opens Training. No names show in the list. Clicking a line (in any of the three choices) opens the programme’s page; “Back” returns to the same choice with the same filters.'],
  ['The programme page','Those who do not manage training see the programme read-only, with no buttons to change it. At the top the title with its status and “Category · Type”. On the left “Programme details” (Period, Trainer, Organising department, Intended for and, where set, Method, Time · duration, Location), “Purpose / description” and “Training material”: the file names and the links; the files open from “Start” / “Continue”, on the training page, where the reading time is also counted. On the right “My participation”: status, due date, result and certificate, with the same button as in the list (Start, Continue, Result or the certificate download); when you do not take part, “Request to attend”, “Request pending” (with ×) or “Rejected”. Below, “Department participation” of your own department in numbers (e.g. “3 of 8 completed”); the Department Manager and the Division Director also see the names of the department’s participants, with status and due date.'],
  ['Department training (Department Manager)','The Department Manager has “New department training” at the top right for a training within their own department. The form asks for the Title, Intended for (the department to begin with), Trainer, start and due dates, Category, Method, Time, Duration, Location, Competency validity and Purpose; the Type is always “Intra-departmental” and the organiser their department, with no cost and no knowledge test. “Save and choose participants” opens the participant picker with the department’s staff only. On the programme page, the “⋯” at the top right of “Programme details” has “Edit” and “Cancel the programme”, “Participants” adds people, the × on someone who has not started removes them, and files can be uploaded under “Training material”. Only department trainings of their own department can be changed, while they are neither completed nor cancelled. The programme shows in “My department”, “Whole hospital”, the Calendar and the training office’s “Programmes”, which sees and corrects it like any programme. Participants open it from “Mine”.'],
  ['Assign to departments','In a programme, “Participants” tab, “Assign to departments” (for those who manage training: Infection Control Lead and Member, Quality Manager, Hospital Admin) assigns the programme to one or more departments or to the “Whole hospital”. All active employees of the departments are added; whoever already participates is not added again and inactive employees are left out. The window shows how many will be added and how many already participate, and asks for confirmation before assigning, e.g. “12 employees from ICU, ED will be added”. With “Also people added to these departments later” every new employee who joins (or moves to) these departments is added automatically, as long as the programme is not completed or cancelled. Above the list it reads “Assigned to: ICU, ED · and new employees” with “Stop adding automatically”; the participants already added stay.'],
  ['Add participants','In a programme, “Participants” tab, “Add participants” shows those who manage training (also the Quality Manager and the Infection Control Member) the hospital’s staff list to choose participants, even without access to the Employee registry: only the name, code, department, profession and email of active employees; those already taking part are marked “Already participating”. “Manual entry” adds people outside the staff.'],
  ['Participation requests','Training managers have the “Participation requests” tab next to “Programmes”, “Annual plan” and “Competence”, with the number waiting. Each line shows the employee with their department, the training, the date and the note, with “Accept” and “Reject”. “Accept” adds the employee to the programme’s participants with the programme’s due date, as “Add participants” does. “Reject” asks for a reason, which the requester sees. Either way the requester gets a notice in their bell straight away (only them). “Pending | All” also shows the answered ones. Inside a programme, the “Overview” says how many requests wait for it, with “Open requests”.'],
  ['The training page in steps','The learner’s page (from the e-mail or from “Start”) shows the title and, on one line, “Category · Method · Trainer · Due date”, then the steps: 1. “Material” (the programme’s files and links in one list; while you read a file the active time is recorded), 2. “Questions” (only when the programme has a knowledge assessment, with the pass threshold and how many are answered), 3. “Evaluation” (of the trainer and the training, 1 to 5 and a comment) and 4. “Submit” (what is still missing, the attendance declaration and “Confirm attendance & submit once”). “Back” and “Next” change step and your answers are kept. After the submission the same link shows the result: the score with “successful” or “Retraining required”, “Completed”, or “Review pending” when a free-text answer awaits review, the certificate with a “Download” button when one was issued, and the material to read. The answers cannot be changed and there is no second submission.'],
  ['Evidence','Attendance, completion and competence are retained as controlled evidence.'],
  ['Type and organising department','The Programmes list shows for each programme its Type (Internal, External, Intra-departmental), as set in the form, and the Department that organised or planned it: the “Organizer / owner”; when a person is named there, their department is shown. Filters has Type and Organising department.']
 ],steps:['Open the programme or assignment.','Perform the action available to your role.','Review completion, results and certificates.'],preview:'training'},
 '/meetings':{title:'Meetings & decisions',summary:'Committees, department meetings and the management review in one section with tabs: meetings, minutes, decisions and action follow-up.',audience:'Committee Secretariat and authorized members',chapters:[
  ['Membership','Members and committee roles have validity periods and history.'],
  ['Meetings','Meetings include participants, quorum, agenda topics and minutes.'],
  ['Decisions & actions','A decision can create a follow-up action with owner and deadline.']
 ],steps:['Open the committee.','Select a meeting or create one if permitted.','Record topics and decisions.','Follow actions through completion.'],preview:'committees'},
 '/documents':{title:'Documents & regulations',summary:'Controlled documents, regulations and legislation in one section with tabs; shared content by role and scope.',audience:'Users with document access',chapters:[
  ['Viewing documents','Standard users see documents shared with them or their department.'],
  ['Management','Creating, publishing and archiving require the relevant permissions.'],
  ['History','Published content should not be silently overwritten. Significant changes retain revision history.']
 ],steps:['Search for the document.','Open the current version.','Use only the actions available to your role.'],preview:'documents'},
 '/library':{title:'Library',summary:'Trusted sources for infection prevention, quality and nursing: links, guidelines, one-page clinical guides and news from the organisations.',audience:'Every user, every role',chapters:[
  ['Links','Organisations by group: Greek bodies, International organisations, Nursing associations & education, Archive. «Suggested» means the platform proposes it and it is not yet confirmed; the Archive keeps organisations that closed or merged, with a note.'],
  ['Guidelines','Each row shows the original title of the guideline (in the Greek interface a Greek title, with the original title under it) and one line of description. The topic chips above the list («All» and one for each topic with three or more guidelines, with the count, on one line) show the guidelines of one topic only; every topic, the organisation and the year are in «Filters». A row opens the details in a card in front of the list (closed with × or Esc), with the link to the publisher page; Limoxis does not republish the text. For a guideline of your own with a title in another language, fill in the optional «Greek title».'],
  ['Clinical guides','One-page guides as cards: organisation and year, the first 3 points of «What we do» and the topics. The card (or Enter) opens the whole guide in a card in front of the screen (closed with × or Esc), with every point, the sources, «Open source» and «Export → Print», which gives a clean A4 page with title, points, sources and date. On the hospital’s own guides the «⋯» at the top right of the card holds «Edit».'],
  ['News','Title, source, date and link from the feeds and pages of the organisations, checked automatically, under the headings «This week» (from Monday), «This month» and «Older», in Greek time. Newest first; when the source gives no date, the day it was found counts. Of the pages only the articles are kept, not the site’s menus. The number on the tab counts only the news of the last 3 days you have not opened. The «Automatic updates» panel shows which source is not answering.'],
  ['Hospital additions','The Hospital Admin and the Quality Manager add, with «Add for the hospital», links, guidelines, clinical guides and announcements that only their hospital sees. The platform content is kept by the Platform Owner in «Library management».']
 ],steps:['Pick a tab.','Search or pick a topic.','Open the guideline or the clinical guide; print the guide if you want it on the ward.','Open the source in a new tab.','If you manage the hospital, add your own with «Add for the hospital».'],preview:'library'},
 '/employees':{title:'Employees',summary:'Administrative staff registry with strict separation of sensitive health information.',audience:'HR, Hospital Admin and authorized roles',chapters:[
  ['Registry','Search and manage administrative employee information.'],
  ['Department & position','Central libraries are used so values remain consistent across the application.'],
  ['Clinical separation','HR access to administrative staff data does not automatically grant access to occupational-health visits or clinical notes.']
 ],steps:['Search for the employee.','Open the record or create a new one if permitted.','Update only the fields that belong to your role.'],preview:'employees'},
 '/kitchen':{title:'Kitchen (HACCP)',summary:'HACCP food safety: receipts and stock per batch, the production day, critical limits, verification and traceability.',audience:'Kitchen manager, cooks (custom role), Quality Manager, Hospital Admin; the Infection Control Lead reads',chapters:[
  ['Page layout','Five tabs in one row: Today (the day of today, what is out of limits and which days wait for verification), Production days (the list of days and the standard menus), Storage (Receipts, Stock and Product list with a selector), Verification & recall (two sections) and HACCP plan. Heat treatments, defrosting, pureeing and the materials in use are recorded and shown inside the production day; the traceability of a batch opens from Stock. The top bar holds only Export and one primary button per tab. Old links open at their new place.'],
  ['Receipt and stock','Each receipt records the supplier, the time, five checks (temperature, packaging, expiry, vehicle, coding) and the products; each product is a batch in stock. A rejected receipt or product adds no stock.'],
  ['Production day','The day opens from the standard menu of its weekday. In it you record the raw materials taken from stock (the oldest batch first; an expired batch cannot be used), the heat parameters of each dish, pureeing, disinfection and the meal plan.'],
  ['Critical limits','Each measurement is marked within or out of limits automatically with the hospital limits (e.g. chilled receipt at most 5 °C, cooking at least 75 °C, chilling to 10 °C within 2 hours). Out of limits needs a corrective action and can be reported to Quality as a deviation.'],
  ['Verification','The kitchen manager or the quality office signs off each day and each defrosting; the record is locked until reopened with a reason. The Days to verify section of the Verification & recall tab shows the days waiting; the sign-off is given inside the production day.'],
  ['Traceability and records','From a batch you see where it was used (day, dish) and back. Export: the daily HACCP sheet, the receipts log, batch traceability and the lists in Excel.'],
  ['Mock recall drill','In the Verification & recall tab, New drill starts from a supplier lot, a product or a dish with a clock running from the start. The app finds at once the supplier and receipt, where it was used (day, dish, meal, portions), the stock and write-offs, and the mass balance (received = used + in stock + written off) against the time target (usually 4 hours). You record who was notified, the actions, the lessons and the result; the report prints or saves as PDF. The drills section warns when no drill was done in the last 12 months. Real recall withdraws the remaining stock with reason Recall and is not part of the drill.']
 ],steps:['Record the receipt with its checks and products.','Open today\'s production and record raw materials and temperatures.','Review what is out of limits and its corrective action.','Sign off the day (kitchen or quality manager).','Run a mock recall drill at least once a year.']},
 '/interviews':{title:'Interviews',summary:'Candidate applications, interviews scored per criterion, the decision and the hiring.',audience:'HR office and Hospital Admin; nobody else sees the applications',chapters:[
  ['Application','The job application holds the position applied for, personal details, contact, education, languages and previous employers. Without the candidate\'s consent to the processing of personal data the application is not saved.'],
  ['Pipeline','Each application goes through New application, Screening, Interview scheduled, Interviewed, Offer and ends Hired, Rejected or Withdrawn. The counters at the top show how many are at each step and filter the list.'],
  ['Interview and evaluation','Scheduling sets the day, time and panel (evaluators and the HR office). The evaluation scores six criteria from 1 to 5; the overall rating is their mean. The evaluation sheet is printed or saved as PDF from Export.'],
  ['Decision and hiring','The decision is Hire, Reserve list or Reject (with a reason). «Hire» creates the employee from the application or links an employee of the registry.'],
  ['Application from a tablet','«Application from a tablet» creates a single-use link for one candidate (valid 24 hours, optionally for a given position): a QR code for the tablet camera, a short code to type at /apply, or «Open on this device» full screen. The candidate, with no account and no access to the rest of the application, fills in step by step the personal details, contact, education, languages (speaking, reading, writing), work experience and «why us», reads and gives the consents (processing of data and the declaration required; other positions and references optional) and signs with a finger. The application appears as a «New application» marked «From tablet»; Details show the consents with their texts and the signature. After sending, the tablet clears itself in 20 seconds.'],
  ['Languages','Each language has a level for speaking, reading and writing (Excellent (fluent), Very good, Good, Fair, Basic) and a certificate. The evaluation sheet prints all three skills.'],
  ['Divisions and departments','In the Divisions tab each division (for example the Nursing Service or the Operations Division) has its members, staff categories and departments. A Division Director automatically gets access, department by department, to the departments of the divisions they direct, and loses it when the departments change, they leave the division or their role changes. Departments given by hand are not changed. The role is read only: their home page shows the departments of the division with their rosters, training and indicators.'],
 ],steps:['Enter the application with the candidate\'s consent, or hand them the tablet with «Application from a tablet».','Schedule the interview with the panel.','Record the evaluation with a score per criterion.','Record the decision and, to hire, create or link the employee.']},
 '/pharmacy':{title:'Pharmacy',summary:'Antimicrobial stewardship, approvals and consumption monitoring.',audience:'Pharmacy, clinical reviewers and Infection Control where authorized',chapters:[
  ['Consumption','The Consumption tab shows the monthly dispensing periods by department and antibiotic, with period (From / To) and department filters and pages; they feed the DDD indicator.'],
  ['Antibiotic approvals','The Antibiotic approvals tab shows the therapies with a restricted antibiotic from surveillance (pending, approved, rejected). Approving or rejecting needs the antimicrobial therapy permission; otherwise the list is read only.'],
  ['Indicators','The Indicators tab calculates the pharmacy indicators of Indicators for the period (e.g. DDD per 100 patient-days, WHO AWaRe Access share) and shows their approved results by period.'],
  ['Connection to surveillance','Therapy data are linked to surveillance episodes without duplicate recording.']
 ],steps:['Open the pending request or record.','Review the required information.','Approve or record only when your role has the relevant permission.'],preview:'pharmacy'},
 '/occupational-health':{title:'Occupational Health',summary:'Employee visits, vaccinations and follow-up with strict confidentiality.',audience:'Occupational Physician and explicitly authorized roles',chapters:[
  ['Visits','Occupational-health visits remain within a protected clinical scope.'],
  ['Vaccinations','Record vaccine, dose, lot, dates and follow-up when required.'],
  ['Follow-up','Expiry dates and required follow-up are surfaced as operational pending work.']
 ],steps:['Search for the employee.','Open the protected clinical record.','Record the visit, vaccination or follow-up.'],preview:'occupational'},
 '/lira':{title:'LIRA AI',summary:'Operational intelligence over data the current user is already allowed to access.',audience:'Roles/capabilities with LIRA access',chapters:[
  ['Ask LIRA','Use focused questions for operational search and synthesis.'],
  ['LIRA Briefing','Summarizes relevant pending work and patterns within the permitted scope.'],
  ['Limits','LIRA does not bypass permissions and does not autonomously change clinical or administrative records.']
 ],steps:['Ask a specific operational question.','Review the information and source context.','Open the underlying record before taking a critical action.'],preview:'lira'},
 '/management':{title:'Management Center',summary:'Organization, users, roles, reference lists and governed configuration.',audience:'Hospital Admin and explicitly authorized administrators',chapters:[
  ['Organization & users','Manage hospital identity, user accounts and activation.'],
  ['Roles & permissions','Permissions define View/Create/Edit/Complete/Approve/Delete/Export/Assign/Manage and must align with backend enforcement.'],
  ['Lists & settings','Departments, organisms, antimicrobials and other shared values are managed centrally.'],
  ['Core content','Hospital changes to core definitions use controlled override/hide patterns where required instead of destroying baseline content.'],
  ['First hospital start','Set up in this order: Lists & settings › Departments, then Users & Roles, then Patient-days (if you have Indicators or Surveillance). The modules you see depend on the package the Platform Owner has set; anything locked is hidden from everyone. All the steps are in the Getting started guide.']
 ],steps:['Choose the management area.','Find the relevant record.','Review scope and impact before changing it.','Save and verify feedback/audit outcome.'],preview:'management'}
}
